                    const savedAddress = await this.saveSessionAddressToProfile();
                    if (!savedAddress) {
                        Salla.notify?.error(Salla.lang.get("common.errors.error_occurred"));
                        this.confirmBtn?.stop();
                        return;
                    }
                    result.address_id = savedAddress.id;
