        if (!config)
            return null;
        const { title, subtitle, buttonText, intent: configIntent } = config;
        const openPayload = configIntent.type === "branch"
            ? { preselected_branch_id: getIntentBranchId(configIntent) }
            : { preselected_address_id: configIntent.address_id };
