    /**
     * Save session address (guest intent) to user profile. Returns the newly saved address or null.
     */
    async saveSessionAddressToProfile() {
        const intent = this.getStoredIntent();
        if (isMapOriginIntent(intent)) {
            const details = intent.address_details;
            const payload = {
                lat: details.lat,
                lng: details.lng,
                ...(details.place_id && { short_address: details.place_id }),
                ...(details.description && { description: details.description }),
            };
            try {
                const { success, address } = await bulletDeliveryAPI.saveAddressLocation(payload);
                if (!success || !address)
                    return null;
                // Persist address_id immediately to avoid duplicate creation on retry — but keep
                // scope_allocated false: the address is saved, not yet allocated, so a later
                // allocation failure must not make hasCompleteIntentForLoggedInUser() think it is.
                this.setStoredIntent({ ...intent, address_id: address.id, scope_allocated: false });
                this.addressCreated.emit({ address });
                return address;
            }
            catch (error) {
                console.error("SallaBulletDelivery: Error saving session address (map)", error);
                return null;
            }
        }
        const countryId = getIntentCountryId(intent);
        const cityId = getIntentCityId(intent);
        const districtId = getIntentDistrictId(intent);
        if (!intent || intent.type !== "address" || !countryId || !cityId)
            return null;
        const countryCode = getIntentCountryCode(intent);
        if (isSaudiArabia(countryCode) && !districtId)
            return null;
        const isSA = isSaudiArabia(countryCode);
        const districtName = intent.address_details?.district?.name ?? "";
        const payload = {
            country_id: countryId,
            region_id: getIntentRegionId(intent),
            city_id: cityId,
            district_id: districtId,
            description: districtName,
        };
        if (isSA) {
            payload.local = districtName;
        }
        try {
            const { success, address } = await bulletDeliveryAPI.saveAddressLocation(payload);
            if (!success)
                return null;
            const savedAddress = address ?? null;
            if (savedAddress) {
                // Persist address_id immediately to avoid duplicate creation on retry — but keep
                // scope_allocated false: the address is saved, not yet allocated, so a later
                // allocation failure must not make hasCompleteIntentForLoggedInUser() think it is.
                this.setStoredIntent({ ...intent, address_id: savedAddress.id, scope_allocated: false });
                this.addressCreated.emit({ address: savedAddress });
            }
            return savedAddress;
        }
        catch (error) {
            console.error("SallaBulletDelivery: Error saving session address", error);
            return null;
        }
    }
